"""Reconstitue le registre des versions à partir de l'historique git et fige les anciennes versions dans versions/ (quand git les a). Idempotent."""
import sys, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[1]; sys.path.insert(0, str(ROOT / "src"))
import tp2_versions as V
def R(art, ver, fait, pourquoi, path=None, commit=None, date=None, note="", pptx=None):
    f = None
    if path:
        p = V.freeze(ROOT / path, ver, commit=commit)
        f = str(p.relative_to(ROOT)) if p else None
        if pptx: V.freeze(ROOT / pptx, ver, commit=commit)
    V.register(art, ver, fait, pourquoi, fichier=f, commit=commit, date=date, note=note + ("" if f or not path else " Fichier non retrouvé dans git."))
